import{_ as o,c as t,o as i,ah as a}from"./chunks/framework.CdwlI3v5.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"_layout":"writeup","ctf":"HSCTF 6","chal":"Multiplication Service","flag":"hsctf{41W4YZ_v4lid473_those_curve_points_a94hg39}","points":488,"category":"crypto"},"headers":[],"relativePath":"writeups/2019/hsctf/Multiplication Service/2019-06-03-Multiplication Service.md","filePath":"writeups/2019/hsctf/Multiplication Service/2019-06-03-Multiplication Service.md"}'),l={name:"writeups/2019/hsctf/Multiplication Service/2019-06-03-Multiplication Service.md"};function c(r,e,n,s,p,d){return i(),t("div",null,[...e[0]||(e[0]=[a('<blockquote><p>Multiplication is safe, right?</p></blockquote><blockquote><p><a href="./problem.sage">problem.sage</a></p></blockquote><p>We are given <a href="./problem.sage">problem.sage</a>, and a server to nc to.</p><h2 id="problem" tabindex="-1">Problem <a class="header-anchor" href="#problem" aria-label="Permalink to “Problem”">​</a></h2><p>The challenge server implements a twisted Edwards curve(Ed448), and has a point multiplication oracle.</p><p>However, the oracle does not check if our point is on the curve, allowing us to input arbituary points</p><h2 id="exploit" tabindex="-1">Exploit <a class="header-anchor" href="#exploit" aria-label="Permalink to “Exploit”">​</a></h2><p>If we multiply the point <code>(0,y)</code> by s, we get <code>(0,y^s)</code>, so we have effectively reduced this into a Diffie-Hellman problem.</p><p>Solving Diffie-Hellman for a large non-smooth number would not be possible. Fortunately, we got bounds on <code>s%pn</code> where <code>pn</code> are multiples of <code>p-1</code>. The usual attack for Diffie-Hellman is with Pohlig-Hellman, and solving the subgroups with BSGS.</p><p>Since we have bounds(b) on the solution to the smaller subgroup, we can store <code>g^n</code> from <code>0</code> to <code>sqrt(b)</code>, and check if <code>h/g^(sqrt(b)n)</code> from <code>0</code> to <code>sqrt(b)</code> is in.</p><p>There are <code>2</code> solutions since <code>g^0=g^1=1(mod 2)</code>, we simply try both solutions, and by using another point, we notice only the case <code>g^0=1(mod2)</code> works, so we simply use that in the CRT to obtain the private key.</p><p>Solution script at <a href="./solve.py">solve.py</a></p>',12)])])}const m=o(l,[["render",c]]);export{u as __pageData,m as default};
